(()=>{const show=t=>{const e=document.getElementById('loginMsg');if(e)e.innerHTML='<div class="error">'+String(t).replace(/[<>&]/g,'')+'</div>';};const load=s=>new Promise((r,j)=>{const x=document.createElement('script');x.src=s;x.onload=r;x.onerror=()=>j(new Error(s));document.head.appendChild(x);});(async()=>{try{if(!window.supabase){try{await load('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2');}catch(e){}}if(!window.supabase){try{await load('https://unpkg.com/@supabase/supabase-js@2');}catch(e){}}if(!window.supabase){show('تعذر تحميل مكتبة الاتصال بقاعدة البيانات. تحقق من اتصال الإنترنت أو إعدادات الحماية.');return;}const x=document.createElement('script');x.src='./app.js';x.onload=()=>{if(typeof window.login!=='function')show('تم تحميل الصفحة لكن التطبيق لم يبدأ بشكل صحيح.');};x.onerror=()=>show('تعذر تحميل ملف التطبيق.');document.head.appendChild(x);}catch(e){show('خطأ في تشغيل المنصة: '+e.message);}})();})();